// Active organizations of the same type, brand and parent (K13 siblings).
func (q *Queries) ListTransferSiblings(ctx context.Context, arg ListTransferSiblingsParams) ([]Organization, error) {
	rows, err := q.db.Query(ctx, listTransferSiblings,
		arg.BrandID,
		arg.ParentID,
		arg.Type,
		arg.OrgID,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []Organization{}
	for rows.Next() {
		var i Organization
		if err := rows.Scan(
			&i.ID,
			&i.Uuid,
			&i.Slug,
			&i.Name,
			&i.City,
			&i.District,
			&i.Phone,
			&i.Address,
			&i.LogoObjectKey,
			&i.Status,
			&i.PlanCode,
			&i.AccessStartsAt,
			&i.AccessEndsAt,
			&i.CreatedAt,
			&i.UpdatedAt,
			&i.DeletedAt,
			&i.Email,
			&i.Website,
			&i.Tagline,
			&i.FooterText,
			&i.PaperSize,
			&i.PrimaryColor,
			&i.Type,
			&i.ParentID,
			&i.BrandID,
			&i.Currency,
			&i.Locale,
			&i.Timezone,
			&i.CountryID,
			&i.ContractPdfKey,
			&i.ContractValidUntil,
			&i.Settings,
			&i.ProvinceID,
			&i.DistrictID,
			&i.PhoneRaw,
			&i.GoogleBusinessUrl,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

