const sumOpenTransferQuantityByUnit = `-- name: SumOpenTransferQuantityByUnit :one
SELECT COALESCE(SUM(i.quantity), 0)::bigint AS open_quantity
FROM stock_transfer_request_items i
JOIN stock_transfer_requests r ON r.id = i.request_id
WHERE i.unit_id = $1
  AND r.from_org_id = $2
  AND r.status IN ('requested', 'approved')
  AND r.id <> $3
`

type SumOpenTransferQuantityByUnitParams struct {
	UnitID           int64 `json:"unit_id"`
	FromOrgID        int64 `json:"from_org_id"`
	ExcludeRequestID int64 `json:"exclude_request_id"`
}

// Fixed barcode quantity on open requests of the giver (excluding one).
func (q *Queries) SumOpenTransferQuantityByUnit(ctx context.Context, arg SumOpenTransferQuantityByUnitParams) (int64, error) {
	row := q.db.QueryRow(ctx, sumOpenTransferQuantityByUnit, arg.UnitID, arg.FromOrgID, arg.ExcludeRequestID)
	var open_quantity int64
	err := row.Scan(&open_quantity)
	return open_quantity, err
}
